<?php
require_once __DIR__.'/../../auth_check.php';require_once __DIR__.'/../model/Database.php';require_once __DIR__.'/../../services/OfficeBudgetForecastService.php';
if(!AccessManager::hasPermission('acces_point_financier')&&!AccessManager::hasPermission('acces_finance')&&!AccessManager::hasPermission('acces_direction')&&!AccessManager::hasPermission('acces_admin')){http_response_code(403);exit('Accès refusé');}
$report=(new OfficeBudgetForecastService(Database::getConnection()))->report($_GET);$view=($_GET['view']??'grouped')==='detailed'?'detailed':'grouped';$format=($_GET['format']??'csv')==='xls'?'xls':'csv';$name='budget_bureau_'.$view.'_'.$report['from'].'_'.$report['to'];
$headers=$view==='grouped'?['Service bénéficiaire actuel','Nb décaissé','Montant finalement décaissé','Moyenne mensuelle observée','Tendance %','Nb attente','Montant attente','Budget mensuel suggéré','Budget suggéré '.$report['targetMonths'].' mois']:['N° fiche','Date','Service bénéficiaire actuel','Source affectation','Statut FEB / décaissement','Bénéficiaire','Montant finalement décaissé','Désignation','Catégorie / précision','Détails'];
$rows=[];if($view==='grouped'){foreach($report['groups'] as $g)$rows[]=[(string)$g['service_name'],(int)$g['spent_count'],(float)$g['spent_amount'],(float)$g['monthly_average'],round((float)$g['trend_percent'],2),(int)$g['pending_count'],(float)$g['pending_amount'],(float)$g['suggested_monthly_budget'],(float)$g['suggested_budget']];}else{foreach($report['details'] as $d)$rows[]=[(string)$d['num_fiche'],substr((string)$d['reference_date'],0,10),(string)$d['service_name'],(string)$d['service_source'],(string)$d['status_label'],(string)$d['beficiaire_fiche'],(float)$d['final_disbursed_amount'],(string)$d['designation_fiche'],(string)$d['precision_fiche'],(string)$d['details_demande']];}
if($format==='csv'){header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="'.$name.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,$headers,';');foreach($rows as $row)fputcsv($out,$row,';');fclose($out);exit;}
header('Content-Type:application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition:attachment; filename="'.$name.'.xls"');echo "\xEF\xBB\xBF";?>
<html><head><meta charset="UTF-8"><style>body{font-family:Arial;color:#172033}table{border-collapse:collapse;width:100%}th{background:#111827;color:#fff;padding:9px}td{border:1px solid #cbd5e1;padding:8px}.title{background:#fbbf24;color:#111827;font-size:18px;font-weight:bold}</style></head><body><table><tr><td class="title" colspan="<?=count($headers)?>">FINEA · PRÉVISION BUDGÉTAIRE BUREAU · <?=htmlspecialchars($report['from'])?> AU <?=htmlspecialchars($report['to'])?></td></tr><tr><?php foreach($headers as $header):?><th><?=htmlspecialchars($header)?></th><?php endforeach;?></tr><?php foreach($rows as $row):?><tr><?php foreach($row as $cell):?><td><?=htmlspecialchars((string)$cell)?></td><?php endforeach;?></tr><?php endforeach;?></table></body></html>
